import{_ as h,C as s,o as l,c as n,E as i,a2 as r}from"./chunks/framework.BdWD-ld-.js";const b=JSON.parse('{"title":"总通过 130 例，动作任务究竟通过几例？","description":"","frontmatter":{"title":"总通过 130 例，动作任务究竟通过几例？","article_type":"experiment-report","edition":"research-center","research_question":"已披露的总通过数与动作成功数，能否确定动作适用子集的完整通过数？","summary":"总通过数与动作成功数不能直接给出动作适用子集的完整通过率。对厂商自报计数的条件性穷举得到 4–24、5–24、0–7 三个可行范围；缺失的是逐例联合结果。","sources":["https://caacgo.cresclab.com/benchmark/gemini-4-hydrogen-november-2026","https://caacgo.cresclab.com/benchmark","https://caacgo.cresclab.com/benchmark/november-2026","https://www.chatbase.co/benchmark/results","https://www.chatbase.co/benchmark"],"date":"2026-11-16","column":"digital-employee","category":"daily","pageClass":"runtime-v6-article","item_id":"SIG-20261116-006","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-16-sig-20261116-006-cover-2026-11-16.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/digital-employee/2026-11-16-sig-20261116-006.md","filePath":"zh/digital-employee/2026-11-16-sig-20261116-006.md","lastUpdated":null}'),p={name:"zh/digital-employee/2026-11-16-sig-20261116-006.md"};function d(k,t,g,E,o,c){const a=s("ArticleCover"),e=s("ArticleTableScroll");return l(),n("div",null,[i(a,{image:"/assets/covers/daily-2026-11-16-sig-20261116-006-cover-2026-11-16.png",kicker:"研究成果",title:"总通过 130 例，动作任务究竟通过几例？",summary:"总通过数与动作成功数不能直接给出动作适用子集的完整通过率。对厂商自报计数的条件性穷举得到 4–24、5–24、0–7 三个可行范围；缺失的是逐例联合结果。",version:"2026-11-16",languageHref:"/en/digital-employee/2026-11-16-sig-20261116-006",languageLabel:"English"}),i(e,{language:"zh"}),t[0]||(t[0]=r(`<h1 id="总通过-130-例-动作任务究竟通过几例" tabindex="-1">总通过 130 例，动作任务究竟通过几例？ <a class="header-anchor" href="#总通过-130-例-动作任务究竟通过几例" aria-label="Permalink to &quot;总通过 130 例，动作任务究竟通过几例？&quot;">​</a></h1><p>一份客服评测同时列出：150 例中有 130 例完整通过，24 例留资或预约动作全部保存。负责验收的人很容易把后一个数字读成“这 24 项任务全部做好了”。但只凭这两个总数，动作适用子集的完整通过数既可能是 24，也可能只有 4。判断这个子集，必须把动作与完整答复按同一案例对齐。下面用两张构造表解释差别，再给出应向评测方索取的最小记录。</p><h2 id="先对齐-150-与-24-的含义" tabindex="-1">先对齐 150 与 24 的含义 <a class="header-anchor" href="#先对齐-150-与-24-的含义" aria-label="Permalink to &quot;先对齐 150 与 24 的含义&quot;">​</a></h2><p>Crescendo Lab（客服智能体厂商）发布的 CAAC Go（网站客服智能体产品）评测报告称，测试使用六个虚构商家、150 条客户消息；固定智能体、指令和工具，替换模型。报告把“完整正确”定义为动作正确、没有添加商家未提供的内容，并使用访客语言；两名模型评分者须同时同意。动作保存另有计数。<a href="https://caacgo.cresclab.com/benchmark/gemini-4-hydrogen-november-2026" target="_blank" rel="noreferrer">模型对照报告</a></p><p>我们采用报告中的三个行名与数字作为输入：</p><table tabindex="0"><thead><tr><th>报告中的模型行名</th><th style="text-align:right;">全体完整通过／150</th><th style="text-align:right;">留资或预约保存／24</th></tr></thead><tbody><tr><td>谷歌模型行（Gemini 4 Hydrogen）</td><td style="text-align:right;">130</td><td style="text-align:right;">24</td></tr><tr><td>第二模型行（Claude Fable 5.2）</td><td style="text-align:right;">131</td><td style="text-align:right;">24</td></tr><tr><td>第三模型行（GPT-6 Astra）</td><td style="text-align:right;">114</td><td style="text-align:right;">7</td></tr></tbody></table><p>来源：上述厂商报告。名称按来源保留，用于识别计数行；本文没有另行核验模型发布身份，也没有调用这些模型。这是厂商陈述，不是独立复测。报告首页还说明，动作检查依据实际动作而非模型评分。<a href="https://caacgo.cresclab.com/benchmark" target="_blank" rel="noreferrer">方法索引</a></p><p>关键差别是：“动作保存”只回答某一步是否发生；“完整通过”还包含答复的其他要求。即便动作成功，答复仍可能因额外编造内容或语言不符而不通过。因此，24 次动作成功不自动等于 24 个完整任务通过。</p><p>以下推导有三个明确前提：150 个案例与 24 个动作适用案例属于同一评测集合；动作适用案例的完整通过必须包含动作成功；除此之外，不假设动作与答复质量独立，也不假设它们如何相关。这是对报告口径的条件性计算。</p><h2 id="同样的总数-可以藏着不同的子集" tabindex="-1">同样的总数，可以藏着不同的子集 <a class="header-anchor" href="#同样的总数-可以藏着不同的子集" aria-label="Permalink to &quot;同样的总数，可以藏着不同的子集&quot;">​</a></h2><p>看 130 例通过、24 次动作成功这一行。其余案例共有 126 例。下面两种分配都与这两个披露总数相容：</p><table tabindex="0"><thead><tr><th>案例分组</th><th style="text-align:right;">构造甲：完整通过</th><th style="text-align:right;">构造甲：未完整通过</th><th style="text-align:right;">构造乙：完整通过</th><th style="text-align:right;">构造乙：未完整通过</th></tr></thead><tbody><tr><td>动作适用的 24 例</td><td style="text-align:right;">4</td><td style="text-align:right;">20</td><td style="text-align:right;">24</td><td style="text-align:right;">0</td></tr><tr><td>其他 126 例</td><td style="text-align:right;">126</td><td style="text-align:right;">0</td><td style="text-align:right;">106</td><td style="text-align:right;">20</td></tr><tr><td>全部 150 例</td><td style="text-align:right;">130</td><td style="text-align:right;">20</td><td style="text-align:right;">130</td><td style="text-align:right;">20</td></tr></tbody></table><p>来源：本次内部算术实验的两张极端可行表。两种构造中，24 例的动作均成功；构造甲中的 20 例仍可因其他答复条件不满足而未完整通过。这些是可能的分配，不是还原出的对话或实测故障。</p><p>构造甲把全部 20 次未通过放在动作子集里；构造乙把它们全部放在其他案例里。它们都保留总通过 130 例和动作成功 24 次。只看这两个边际计数——分别汇总、没有逐例交叉关系的计数——无法分辨哪一种更接近实际。</p><p>反过来说，真实结果完全可能是构造乙。我们的结论不是“动作子集很差”，而是“总数没有告诉我们它究竟怎样”。这也解释了为什么不能把最坏可行值直接写成厂商的真实成绩。</p><h2 id="区间来自容量约束-不来自抽样误差" tabindex="-1">区间来自容量约束，不来自抽样误差 <a class="header-anchor" href="#区间来自容量约束-不来自抽样误差" aria-label="Permalink to &quot;区间来自容量约束，不来自抽样误差&quot;">​</a></h2><p>用 N（总案例数）、E（动作适用数）、P（全体完整通过数）、S（动作成功数）和 x（动作适用且完整通过的案例数）表示各项计数。其他案例最多容纳 N−E 个通过，因此至少有 P−(N−E) 个通过落在动作子集里。同时，x 不能超过动作适用数、全体通过数或动作成功数。</p><p>对本次相容的输入，可行整数范围为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>max(0, P - (N - E)) ≤ x ≤ min(E, P, S)</span></span></code></pre></div><p>本次研究分析阶段已经执行内部穷举：逐一检查整数 x，要求各分组计数非负、全体计数一致，并要求完整通过包含动作成功。本文复用该同日实验，不新增模型评测。结果如下：</p><table tabindex="0"><thead><tr><th>输入行（与上表顺序一致）</th><th style="text-align:right;">动作子集完整通过数的可行范围</th><th style="text-align:right;">相容整数分配数</th></tr></thead><tbody><tr><td>130 例通过，24 次动作成功</td><td style="text-align:right;">4–24</td><td style="text-align:right;">21</td></tr><tr><td>131 例通过，24 次动作成功</td><td style="text-align:right;">5–24</td><td style="text-align:right;">20</td></tr><tr><td>114 例通过，7 次动作成功</td><td style="text-align:right;">0–7</td><td style="text-align:right;">8</td></tr></tbody></table><p>来源：本次内部实验；见<a href="/joinwell52/assets/evidence/2026-11-16-sig-20261116-006/conditional-counts.json">条件性枚举结果</a>。所有范围都以 24 例为子集分母。最后一行尤其能看出动作数据的作用：如果只知道总通过 114 例，子集可行范围仍是 0–24；加入“仅 7 次动作成功”及必要条件后，上界才缩到 7。</p><p>这些是可行性边界，不是置信区间，不表示各个值等可能，也不评估评分者准确性。要复核已有实验的核心枚举，可以使用下面的等价简式；它检查的是算术关系，不访问厂商系统：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> feasible_counts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(N, E, P, S):</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [x </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> x </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> range</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(E </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">            if</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> P </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> x </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> N </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> E </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">and</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> x </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> S]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">assert</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> feasible_counts(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">150</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">24</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">130</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">24</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> list</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">range</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">25</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">assert</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> feasible_counts(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">150</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">24</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">131</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">24</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> list</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">range</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">25</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">assert</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> feasible_counts(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">150</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">24</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">114</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">7</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> list</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">range</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span></code></pre></div><p>仅当输入本身满足 0≤S≤E≤N、0≤P≤N，且完整通过确实要求动作成功时，这个简式才适用。本次三个输入满足这些约束。</p><h2 id="另一个评测把阶段分开-却仍没有成交结果" tabindex="-1">另一个评测把阶段分开，却仍没有成交结果 <a class="header-anchor" href="#另一个评测把阶段分开-却仍没有成交结果" aria-label="Permalink to &quot;另一个评测把阶段分开，却仍没有成交结果&quot;">​</a></h2><p>Chatbase（另一家客服智能体厂商）的独立编写报告提供了一个有用的方法对照：图片购物测试分别列出接收图片、找到商品、加入购物车、到达结账。它称自身在 9 个受测店铺的每个阶段均达到 9／9；其他产品的样本分母不一，部分阶段标为不支持。这里的单位是店铺和所达阶段，不能套进上面的 150 案例计算。<a href="https://www.chatbase.co/benchmark/results" target="_blank" rel="noreferrer">完整结果</a></p><p>分开阶段比把所有步骤压成一个“完成”更容易解释，但到达结账仍没有给出支付或成交数量。本文不把缺失的成交数补成零，也不补成九。这个对照支持的是测量边界：一份报告可以明确某一步发生过，同时仍缺少下一步的结果。</p><p>两家报告的作者主体不同，测试对象与方法也不同；它们是两个独立来源，不是互相验证的两次实验。前者控制同一智能体中的模型，后者观察不同店铺的部署。不能合并分数，不能据此给出统一排名。两名模型评分者或同一厂商的多篇报告，也不会增加独立作者主体数。<a href="https://www.chatbase.co/benchmark" target="_blank" rel="noreferrer">后者的方法概述</a></p><h2 id="下一张评测表应保留什么" tabindex="-1">下一张评测表应保留什么 <a class="header-anchor" href="#下一张评测表应保留什么" aria-label="Permalink to &quot;下一张评测表应保留什么&quot;">​</a></h2><p>我们的工程建议是先保存逐例联合记录，再计算总分。对于一个需要保存预约请求的案例，应分别记录：该例是否适用动作、保存动作是否成功、完整答复是否通过。记录必须用同一个案例标识连接，才能直接数出目标子集；真实业务是否接受预约，是另外一项下游验收。</p><table tabindex="0"><thead><tr><th>阶段与输入</th><th>建议责任主体</th><th>应保存的输出</th><th>何时不能声称完成</th></tr></thead><tbody><tr><td>案例与预期任务</td><td>评测设计者</td><td>动作适用性及预期动作</td><td>适用性未定义</td></tr><tr><td>执行案例</td><td>执行器与动作记录方</td><td>动作结果及对应记录</td><td>只有口头承诺，没有动作记录</td></tr><tr><td>核对完整答复</td><td>评分与复核者</td><td>逐例通过结果及原因</td><td>评分缺失或口径不一致</td></tr><tr><td>汇总同一案例的各项结果</td><td>评测汇总者</td><td>动作适用且完整通过的数量</td><td>案例无法匹配，只有分项总数</td></tr><tr><td>预约请求或留资交付</td><td>接收业务方</td><td>单独的接收、持久保存或履约结果</td><td>尚未观察业务接收或最终结果</td></tr></tbody></table><p>这是建议的责任链，不是两家厂商已经实现的系统描述。实际台账还应保留评测版本与重评记录，避免把不同轮次的总数拼在一起。比如，来源说明第三行计数在补评分后发生变化；本文使用当前报告的 114，而没有混入另一版本的数值。<a href="https://caacgo.cresclab.com/benchmark/gemini-4-hydrogen-november-2026" target="_blank" rel="noreferrer">重评与方法限制</a></p><p>如果评测已经提供同一案例的适用性、动作和完整通过结果，本次不可识别问题就不适用：可以直接数出 x，无须再给范围。对于只回答问题、没有动作子集的评测，也不应硬套这套分组。</p><h2 id="证据仍停在哪里" tabindex="-1">证据仍停在哪里 <a class="header-anchor" href="#证据仍停在哪里" aria-label="Permalink to &quot;证据仍停在哪里&quot;">​</a></h2><p>本文的外部材料是两家商业主体对自身方法与结果的披露；它们支持“报告写了什么”，并不独立证明成绩可靠。内部实验只检验这些计数在所列前提下允许哪些分配，没有访问原始对话、评分提示、客户记录或真实交易。完整实验记录保存在本地；附带的<a href="/joinwell52/assets/evidence/2026-11-16-sig-20261116-006/conditional-counts.json">脱敏计数结果</a>保留输入、假设、全部可行表与边界，供读者核算，不包含客户数据。</p><p>来源还提示单次运行、评分缺失与重评等限制；关联的方法说明称测试关闭了生产环境的某项留资兜底。因此不能把测试中的动作遗漏率直接当成生产损失率。<a href="https://caacgo.cresclab.com/benchmark/gemini-4-hydrogen-november-2026" target="_blank" rel="noreferrer">模型报告</a>、<a href="https://caacgo.cresclab.com/benchmark/november-2026" target="_blank" rel="noreferrer">关联方法说明</a></p><p>真正缺少的不是另一个总分，而是能回答两个问题的记录：动作适用案例里，究竟哪些完整通过；保存之后，又由谁确认接收或履约。拿到前者，才能结束本文的算术不确定性；拿到后者，才有资格讨论相应的业务结果。</p>`,38))])}const F=h(p,[["render",d]]);export{b as __pageData,F as default};
